import{_ as e}from"./chunks/files.B17OUyrr.js";import{_ as o,c as r,o as s,a2 as i}from"./chunks/framework.CIiVzG-O.js";const b=JSON.parse('{"title":"Comparar archivos","description":"Abra dos archivos uno al lado del otro, lea los cambios coloreados, salte entre ellos y edite o comparta.","frontmatter":{"title":"Comparar archivos","description":"Abra dos archivos uno al lado del otro, lea los cambios coloreados, salte entre ellos y edite o comparta."},"headers":[],"relativePath":"es/guide/files.md","filePath":"es/guide/files.md","lastUpdated":1794296122000}'),n={name:"es/guide/files.md"};function l(t,a,c,d,m,u){return s(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="comparar-archivos" tabindex="-1">Comparar archivos <a class="header-anchor" href="#comparar-archivos" aria-label="Permalink to &quot;Comparar archivos&quot;">​</a></h1><p>Esta es la vista con la que casi todo el mundo empieza: dos versiones del mismo archivo, una junto a otra, con cada diferencia marcada.</p><img src="'+e+'" alt="Dos archivos de texto uno al lado del otro con cambios coloreados" class="guide-shot"><h2 id="abra-dos-archivos" tabindex="-1">Abra dos archivos <a class="header-anchor" href="#abra-dos-archivos" aria-label="Permalink to &quot;Abra dos archivos&quot;">​</a></h2><p>Use <strong>Archivo → Abrir</strong> o simplemente arrastre dos archivos a la ventana de qDiff. ¿Necesita conciliar tres versiones? Añada un tercer panel: se aplican las mismas reglas de color. Las comparaciones recientes se conservan en la pantalla de bienvenida para la próxima vez.</p><h2 id="que-significan-los-colores" tabindex="-1">Qué significan los colores <a class="header-anchor" href="#que-significan-los-colores" aria-label="Permalink to &quot;Qué significan los colores&quot;">​</a></h2><ul><li><strong>Rojo suave</strong> — el contenido de este lado se eliminó o pertenece a la versión anterior.</li><li><strong>Verde suave</strong> — el contenido se añadió o pertenece a la versión más reciente.</li><li><strong>Color más intenso dentro de una línea</strong> — las palabras que cambiaron exactamente. Una sola palabra modificada nunca queda oculta dentro de toda una línea coloreada.</li></ul><p>Ambos lados se desplazan a la vez, de modo que las dos versiones permanecen siempre en la misma línea.</p><h2 id="muevase-entre-los-cambios" tabindex="-1">Muévase entre los cambios <a class="header-anchor" href="#muevase-entre-los-cambios" aria-label="Permalink to &quot;Muévase entre los cambios&quot;">​</a></h2><p>Haga clic en el estrecho mapa situado junto al texto para saltar a cualquier punto del archivo, o use los botones anterior / siguiente (que también tienen atajos de teclado) para recorrer los cambios uno a uno. El mapa también le indica dónde se encuentra dentro de un documento largo.</p><h2 id="corrija-sobre-la-marcha" tabindex="-1">Corrija sobre la marcha <a class="header-anchor" href="#corrija-sobre-la-marcha" aria-label="Permalink to &quot;Corrija sobre la marcha&quot;">​</a></h2><p>Cualquiera de los lados se puede editar y deshacer. Para cada cambio puede copiarlo al otro lado, reemplazarlo o eliminarlo, directamente desde la comparación y sin abrir otro editor. Cuando termine, guarde como de costumbre.</p><div class="tip custom-block"><p class="custom-block-title">Comparta una imagen</p><p>Seleccione un cambio y expórtelo como imagen: una composición limpia en dos columnas, fácil de pegar en un mensaje o en una revisión. La imagen exportada no lleva ninguna marca.</p></div><p>A continuación: <a href="./folders.html">compare carpetas completas</a>.</p>',14)])])}const v=o(n,[["render",l]]);export{b as __pageData,v as default};
